writeFileSync(out, JSON.stringify({ numPassedTests: 3, numFailedTests: fail ? 1 : 0, testResults: [{ name: process.cwd() + "/src/App.test.tsx",
  assertionResults: [{ status: "passed", fullName: "renders" }, ...(fail ? [{ status: "failed", fullName: "App increments the counter", failureMessages: ["expected 1 to be 2"] }] : [])] }] }))
